class DbfieldsOptionsResource(Resource):
    """`client.dbfields.options`"""

    def create(
        self,
        field_id: int,
        *,
        name: _t.Union[str, UnsetType] = UNSET,
        sort_key: _t.Union[int, UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.DbFieldOption:
        """
        Create a database-field option

        `POST /dbfields/{fieldId}/options`

        Creates an option in the selected field’s backing table. Use the metadata endpoint to determine the complete request shape. Fields without a backing table do not support this operation.

        Args:
            field_id: Database-field definition ID returned by GET /dbfields.
            name: Common option label. Custom selection-table labels contain 1–30 characters.
            sort_key: Display order, required for custom selection tables and any metadata exposing a non-auto-increment `sortKey` column.

        Example::

            result = client.dbfields.options.create(200, name="Vegetarian")
            print(result.name)
        """
        return _t.cast(models.DbFieldOption, self._call('POST', f"/dbfields/{_seg(field_id)}/options", [], _body({'name': name, 'sortKey': sort_key}, extra_body), models.DbFieldOption, envelope=True))

    def delete(
        self,
        field_id: int,
        option_id: int,
        *,
        dry_run: _t.Optional[bool] = None,
    ) -> None:
        """
        Delete a database-field option

        `DELETE /dbfields/{fieldId}/options/{optionId}`

        Deletes an option row from the selected field’s backing masterdata table through the shared deletion service. References can block deletion. `dryRun=true` returns the deletion preview with HTTP 409 without removing the row.

        Args:
            field_id: Database-field definition ID returned by GET /dbfields.
            option_id: Option row ID in this field’s backing table.
            dry_run: If true, the deletion is only simulated and the option is not deleted. The response describes whether the option can be deleted.

        Example::

            client.dbfields.options.delete(200, 3)
        """
        self._raw('DELETE', f"/dbfields/{_seg(field_id)}/options/{_seg(option_id)}", _query([('dryRun', dry_run)]), None)

    def list(
        self,
        field_id: int,
    ) -> _t.List[models.DbFieldOption]:
        """
        List options for a database field

        `GET /dbfields/{fieldId}/options`

        Lists option rows from the field’s backing masterdata table. Rows are ordered by `sortKey` when available. Fields without a backing table return an empty list. Read the option metadata to interpret row keys.

        Args:
            field_id: Database-field definition ID returned by GET /dbfields.

        Example::

            for option in client.dbfields.options.list(200):
                print(option.name)
        """
        return _t.cast(_t.List[models.DbFieldOption], self._call('GET', f"/dbfields/{_seg(field_id)}/options", [], None, _t.List[models.DbFieldOption], envelope=True))

    def list_metadata(
        self,
        field_id: int,
    ) -> _t.List[models.DbFieldOptionColumn]:
        """
        Get metadata for field options

        `GET /dbfields/{fieldId}/options/metadata`

        Describes the actual SQL columns of the selected field’s backing option table as API properties. Audit columns are omitted. Use this operation only for fields backed by a table.

        Args:
            field_id: Database-field definition ID returned by GET /dbfields.

        Example::

            for metadata in client.dbfields.options.list_metadata(200):
                print(metadata.name)
        """
        return _t.cast(_t.List[models.DbFieldOptionColumn], self._call('GET', f"/dbfields/{_seg(field_id)}/options/metadata", [], None, _t.List[models.DbFieldOptionColumn], envelope=True))

    def update(
        self,
        field_id: int,
        option_id: int,
        *,
        name: _t.Union[str, UnsetType] = UNSET,
        sort_key: _t.Union[int, UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.DbFieldOption:
        """
        Update a database-field option

        `PUT /dbfields/{fieldId}/options/{optionId}`

        Updates an option row using all non-auto-increment columns from the metadata endpoint. This operation replaces the complete metadata-defined row and supports only fields backed by a table.

        Args:
            field_id: Database-field definition ID returned by GET /dbfields.
            option_id: Option row ID in this field’s backing table.
            name: Common option label. Custom selection-table labels contain 1–30 characters.
            sort_key: Display order, required for custom selection tables and any metadata exposing a non-auto-increment `sortKey` column.

        Example::

            result = client.dbfields.options.update(200, 3, name="Vegetarian")
            print(result.name)
        """
        return _t.cast(models.DbFieldOption, self._call('PUT', f"/dbfields/{_seg(field_id)}/options/{_seg(option_id)}", [], _body({'name': name, 'sortKey': sort_key}, extra_body), models.DbFieldOption, envelope=True))


class EventsAgendaResource(Resource):
    """`client.events.agenda`"""

    def __init__(self, core: _t.Any) -> None:
        super().__init__(core)
        self.items = EventsAgendaItemsResource(core)

    def delete(
        self,
        event_id: int,
    ) -> None:
        """
        Detach the agenda from an event

        `DELETE /events/{eventId}/agenda`

        Removes only the link between the event and its agenda. Other events sharing this agenda retain their links and content. If no event links remain, the unused agenda is cleaned up later. A locked agenda can also be detached. Requires agenda editing access for the event.

        Args:
            event_id: ID of Event

        Example::

            client.events.agenda.delete(42)
        """
        self._raw('DELETE', f"/events/{_seg(event_id)}/agenda", [], None)

    def export(
        self,
        event_id: int,
        *,
        format: _t.Literal['PRO_PRESENTER_6', 'PRO_PRESENTER_7', 'SONG_BEAMER'],
        append_arrangement: bool,
        export_songs: bool,
        with_category: bool,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.AgendaExport:
        """
        Export event agenda

        `POST /events/{eventId}/agenda/export`

        Generates a presenter import archive for an event agenda. Requires a super administrator, an event administrator, "view agenda" or "edit agenda" for the event calendar, or involvement in the event. The current exporters use all items from the shared agenda, including items hidden for the requested event; the archive is not filtered to that event's visible positions. Locked and unlocked agendas can be exported.

        Args:
            event_id: ID of Event
            format: Target presenter format. The generated archive is returned through a download URL in the JSON response.
                Allowed values: `PRO_PRESENTER_6`, `PRO_PRESENTER_7`, `SONG_BEAMER`.
            append_arrangement: Append the selected arrangement name to exported song captions and generated fallback file names. Existing attached files retain their file names.
            export_songs: Include available song files for the target software. The first matching file of the selected arrangement is used. For SongBeamer, the song's default arrangement can provide a fallback `.sng` file. When disabled, song references point to files expected in the presenter library. No song-file conversion is performed.
            with_category: For `SONG_BEAMER` with `exportSongs`=`false`, prefix generated song file references with the song category as a directory. Has no effect with embedded song files or for either ProPresenter format.

        Example::

            agenda = client.events.agenda.export(
                42,
                format="SONG_BEAMER",
                append_arrangement=True,
                export_songs=True,
                with_category=False,
            )
            print(agenda.url)
        """
        return _t.cast(models.AgendaExport, self._call('POST', f"/events/{_seg(event_id)}/agenda/export", _query([('format', format)]), _body({'appendArrangement': append_arrangement, 'exportSongs': export_songs, 'withCategory': with_category}, extra_body), models.AgendaExport, envelope=True))

    def get(
        self,
        event_id: int,
    ) -> models.Agenda:
        """
        Get agenda for event

        `GET /events/{eventId}/agenda`

        Returns the event's running plan, including all ordered items, shared lock state and calculated times for linked events. Header, text and song items use different response fields; hidden items remain in `items` with a `null` entry in `startTimes`. Responsibility placeholders are resolved for the requested event and service-group notes are visibility-filtered.

        Args:
            event_id: ID of Event

        Example::

            agenda = client.events.agenda.get(42)
            print(agenda.name)
        """
        return _t.cast(models.Agenda, self._call('GET', f"/events/{_seg(event_id)}/agenda", [], None, models.Agenda, envelope=True))

    def integrate(
        self,
        event_id: int,
        *,
        event_id_2: int,
    ) -> models.Agenda:
        """
        Integrate agenda with another event

        `POST /events/{eventId}/agenda/integrate`

        Links the target event in the path to the existing agenda of the source event given by `event_id`. This creates a shared agenda, not a copy: item IDs, content and lock state are shared with all already linked events. Event dates remain independent and item times are calculated per event. Hidden-item settings of the source event are not copied to the new link. Requires agenda editing permission for the target and agenda viewing permission for the source.

        Args:
            event_id: ID of Event
            event_id_2: Source event ID. Its agenda is shared with the target event in the path; the two event IDs must differ.

        Example::

            agenda = client.events.agenda.integrate(42, event_id_2=1337)
            print(agenda.name)
        """
        return _t.cast(models.Agenda, self._call('POST', f"/events/{_seg(event_id)}/agenda/integrate", _query([('event_id', event_id_2)]), None, models.Agenda, envelope=True))

    def list_songs(
        self,
        event_id: int,
    ) -> _t.List[models.Song]:
        """
        Get songs referenced by an agenda

        `GET /events/{eventId}/agenda/songs`

        Returns the distinct songs referenced by song items with an assigned arrangement in the event's agenda. Includes songs from positions hidden for this event because the complete shared agenda is inspected. Multiple positions or arrangements referring to one song produce one song record. Each record includes all arrangements of that song, not only the arrangement selected in the agenda.

        Args:
            event_id: ID of Event

        Example::

            for song in client.events.agenda.list_songs(42):
                print(song.name)
        """
        return _t.cast(_t.List[models.Song], self._call('GET', f"/events/{_seg(event_id)}/agenda/songs", [], None, _t.List[models.Song], envelope=True))

    def lock(
        self,
        event_id: int,
    ) -> None:
        """
        Lock a shared agenda

        `POST /events/{eventId}/agenda/lock`

        Locks the event's agenda against content changes. Events integrated with this event share the same agenda and therefore the same lock state. This is an agenda state, not a temporary editing lock owned by the caller. Calling lock on an already locked agenda returns `403`. Requires agenda editing access for the event.

        Args:
            event_id: ID of Event

        Example::

            client.events.agenda.lock(42)
        """
        self._raw('POST', f"/events/{_seg(event_id)}/agenda/lock", [], None)

    def unlock(
        self,
        event_id: int,
    ) -> None:
        """
        Unlock a shared agenda

        `POST /events/{eventId}/agenda/unlock`

        Unlocks the event's agenda so its content can be edited again. The change applies to all events sharing the agenda. Calling unlock on an already unlocked agenda returns `403`. Any caller with the required agenda editing permission can unlock it; the caller need not be the person who locked it. Requires agenda editing access for the event.

        Args:
            event_id: ID of Event

        Example::

            client.events.agenda.unlock(42)
        """
        self._raw('POST', f"/events/{_seg(event_id)}/agenda/unlock", [], None)

    def update(
        self,
        event_id: int,
        *,
        template_id: _t.Optional[int] = None,
        event_id_2: _t.Optional[int] = None,
        body: _t.Optional[_t.Union[models.AgendaCreate, models.AgendaUpdate]] = None,
    ) -> models.Agenda:
        """
        Create or update agenda

        `PUT /events/{eventId}/agenda`

        Creates an agenda for an event that has none, or updates its existing agenda. The operation always returns `200`. Supply `calendarId` when creating without a copy source. On update, the agenda must be unlocked; changes to a shared agenda affect every linked event. Requires agenda editing permission for the target and viewing permission for a selected source agenda or template.

        Args:
            event_id: ID of Event
            template_id: Agenda template to copy. Replaces the target items with copies and supplies fallback metadata values. Mutually exclusive with `event_id` and the items body field.
            event_id_2: Event whose agenda should be copied. Must differ from the target event ID. Replaces target items with copies and supplies fallback metadata values. Mutually exclusive with `template_id` and the items body field.

        Example::

            result = client.events.agenda.update(42)
            print(result.name)
        """
        return _t.cast(models.Agenda, self._call('PUT', f"/events/{_seg(event_id)}/agenda", _query([('template_id', template_id), ('event_id', event_id_2)]), _body(body), models.Agenda, envelope=True))


