class FinanceAccountclassesResource(Resource):
    """`client.finance.accountclasses`"""

    def create(
        self,
        *,
        account_type_id: int,
        name: str,
        include_profit_loss: _t.Union[bool, UnsetType] = UNSET,
        sort_key: _t.Union[int, UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.AccountClass:
        """
        Create a new account class

        `POST /finance/accountclasses`

        Creates finance master data. Account classes group account groups within one account type. The hierarchy is account type → account class → account group → account. Requires finance “edit masterdata”. Names must be unique across this resource. The successful response uses HTTP 200.

        Args:
            account_type_id: ID of the related account type.
            include_profit_loss: Adds the profit-and-loss total to this class in reports. At most one account class in the installation may enable this flag; it is not restricted by account type. Omitted values default to false, including on update.
            name: Unique account-class name. The controller does not trim the name or enforce a length limit.
            sort_key: Sort order of the account class.

        Example::

            result = client.finance.accountclasses.create(account_type_id=3, name="Anlagevermögen")
            print(result.name)
        """
        return _t.cast(models.AccountClass, self._call('POST', "/finance/accountclasses", [], _body({'accountTypeId': account_type_id, 'includeProfitLoss': include_profit_loss, 'name': name, 'sortKey': sort_key}, extra_body), models.AccountClass, envelope=True))

    def delete(
        self,
        id: int,
        *,
        dry_run: _t.Optional[bool] = None,
    ) -> None:
        """
        Delete an account class

        `DELETE /finance/accountclasses/{id}`

        Deletes this definition if no account groups reference it. Requires finance “edit masterdata”. With dry_run=true no deletion occurs and HTTP 409 returns the conflict report, including when deletion would be allowed.

        Args:
            id: ID of Entity
            dry_run: If set to true, the deletion is simulated but nothing will be deleted.

        Example::

            client.finance.accountclasses.delete(1)
        """
        self._raw('DELETE', f"/finance/accountclasses/{_seg(id)}", _query([('dry_run', dry_run)]), None)

