class GroupsRolesResource(Resource):
    """`client.groups.roles`"""

    def list(
        self,
        group_id: _t.Union[int, str],
    ) -> _t.List[models.GroupRole]:
        """
        Get all roles for this group

        `GET /groups/{groupId}/roles`

        Returns the roles configured for one group, including inactive roles. Each entry combines a shared role definition from the group's type with settings specific to this group, such as chat access, check-in QR codes and participant capacity.
        id is the group-specific role settings ID used by PATCH /groups/{groupId}/roles/{roleId}. groupTypeRoleId links to the shared definition from GET /group/roles; do not interchange these IDs. isActive describes whether the role is enabled in this group, not the membership status of any person.
        Requires authentication and permission to view the group. Accepts its numeric ID or chat GUID. Results are not paginated and are sorted by the shared role's type and sortKey ascending. meta.count includes all returned roles.

        Args:
            group_id: Numeric ID or chat GUID of the group whose role settings to retrieve.

        Example::

            for role in client.groups.roles.list(42):
                print(role.name)
        """
        return _t.cast(_t.List[models.GroupRole], self._call('GET', f"/groups/{_seg(group_id)}/roles", [], None, _t.List[models.GroupRole], envelope=True))

    def patch(
        self,
        group_id: int,
        role_id: int,
        *,
        can_read_chat: _t.Union[bool, UnsetType] = UNSET,
        can_write_chat: _t.Union[bool, UnsetType] = UNSET,
        counts_towards_seats: _t.Union[bool, UnsetType] = UNSET,
        force_two_factor_auth: _t.Union[bool, UnsetType] = UNSET,
        grow_path_id: _t.Union[_t.Optional[int], UnsetType] = UNSET,
        html_template_ids: _t.Union[_t.List[int], UnsetType] = UNSET,
        is_active: _t.Union[bool, UnsetType] = UNSET,
        receive_qr_code: _t.Union[bool, UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.GroupRole:
        """
        Update role settings for a group

        `PATCH /groups/{groupId}/roles/{roleId}`

        Updates settings for one role in one group. Use the entry's id from GET /groups/{groupId}/roles as roleId, not its groupTypeRoleId. This does not rename or reclassify the shared role definition.
        Send only the settings to change. Omitted fields are preserved. growPathId=null clears the growth-path association; htmlTemplateIds=[] clears the template list. A supplied template list replaces the previous list. The default role cannot be deactivated. Returns the complete updated GroupRole in data, without meta.
        Requires authentication and permission to view the group. Chat settings require one of administer groups, edit group, edit groups of grouptype or +admin group chat for this group. The other role settings except htmlTemplateIds require one of administer groups, edit group or edit groups of grouptype. Adding document templates requires one of administer groups, edit group, edit groups of grouptype or +edit group basic settings, plus the churchcore permission use church html templates for each added template. Templates must belong to the group-membership document domain.

        Args:
            group_id: ID of group
            role_id: ID of group role. This is not the group type role. The group role has a reference to the group type role and sets specific settings for the role in this group.
            can_read_chat: Allow members in this role to read the group chat.
            can_write_chat: Allow members in this role to write in the group chat.
            counts_towards_seats: Count memberships in this role towards the group's participant capacity.
            force_two_factor_auth: Require members in this role to use two-factor authentication.
            grow_path_id: Set the growth-path association for this role in this group. Send null to clear it; omit the field to keep the current value.
            html_template_ids: Replace the list of HTML templates available for membership documents in this role. Send an empty array to clear the list; null is not accepted. Newly added templates must support group membership documents.
            is_active: Enable or disable this role in the group. The default role cannot be deactivated. This does not set the membership status of individual people.
            receive_qr_code: Enable check-in QR codes for members in this role.

        Example::

            result = client.groups.roles.patch(42, 1, can_read_chat=True)
            print(result.name)
        """
        return _t.cast(models.GroupRole, self._call('PATCH', f"/groups/{_seg(group_id)}/roles/{_seg(role_id)}", [], _body({'canReadChat': can_read_chat, 'canWriteChat': can_write_chat, 'countsTowardsSeats': counts_towards_seats, 'forceTwoFactorAuth': force_two_factor_auth, 'growPathId': grow_path_id, 'htmlTemplateIds': html_template_ids, 'isActive': is_active, 'receiveQRCode': receive_qr_code}, extra_body), models.GroupRole, envelope=True))


