class PersonsDevicesResource(Resource):
    """`client.persons.devices`"""

    def delete(
        self,
        person_id: int,
        device_id: str,
    ) -> None:
        """
        Delete device for person

        `DELETE /persons/{personId}/devices/{deviceId}`

        Removes the registration identified by personId/deviceId. Requires the person themselves, a super administrator, or administer persons permission. An unknown registration is a successful no-op. Returns 204 without a response body; no other device registrations are deleted.

        Args:
            person_id: ID of person

        Example::

            client.persons.devices.delete(42, "abc123")
        """
        self._raw('DELETE', f"/persons/{_seg(person_id)}/devices/{_seg(device_id)}", [], None)

    def get(
        self,
        person_id: int,
        device_id: str,
    ) -> models.Device:
        """
        Get specified device

        `GET /persons/{personId}/devices/{deviceId}`

        Returns the device identified by the personId/deviceId pair. Requires the same person-settings read access as the device list. Unknown registrations return 404. deviceId is the registration identifier; the deprecated response id is actually the push token. Reading does not refresh expiration.

        Args:
            person_id: ID of person

        Example::

            device = client.persons.devices.get(42, "abc123")
            print(device.app_version)
        """
        return _t.cast(models.Device, self._call('GET', f"/persons/{_seg(person_id)}/devices/{_seg(device_id)}", [], None, models.Device, envelope=True))

    def list(
        self,
        person_id: int,
    ) -> _t.List[models.Device]:
        """
        Get all registered devices for person

        `GET /persons/{personId}/devices`

        Lists all device registrations stored for the person, including registrations whose expirationDate has passed until cleanup removes them. Requires access to the person’s settings: the person themselves, a super administrator, or someone with administer persons permission. The read policy also accepts the special person ID -1. There is no pagination or guaranteed order, and this operation does not refresh expiration.

        Args:
            person_id: ID of person

        Example::

            for device in client.persons.devices.list(42):
                print(device.app_version)
        """
        return _t.cast(_t.List[models.Device], self._call('GET', f"/persons/{_seg(person_id)}/devices", [], None, _t.List[models.Device], envelope=True))

    def update(
        self,
        person_id: int,
        device_id: str,
        *,
        type_: _t.Literal['APN', 'FCM'],
        app_version: _t.Union[_t.Optional[str], UnsetType] = UNSET,
        push_id: _t.Union[_t.Optional[str], UnsetType] = UNSET,
        version: _t.Union[_t.Optional[str], UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> _t.List[models.Device]:
        """
        Create or update new device for person

        `PUT /persons/{personId}/devices/{deviceId}`

        Creates or refreshes the registration identified by personId/deviceId and returns the person’s complete device list. Requires access to update the person’s settings: the person themselves, a super administrator, or someone with administer persons permission. type is required on every call. Expiration is extended by three months, or one day during simulation. Omitted pushId becomes deviceId; empty pushId preserves the previous token; null clears it. Omitted appVersion clears the previous version. Other registrations of the same person with the same non-null push token are removed. Saving is transactional. When chat is active, a supplied appVersion outside simulation also sets the person’s hasMatrixUser setting.

        Args:
            person_id: ID of person
            app_version: App version accepted by the version validator, such as 1.2.3. Omission or null clears the stored version.
            push_id: Trimmed push token. Omission replaces the token with deviceId; null clears it; an empty or whitespace-only string preserves the previous token (null on a new device).
            type_: Push platform: APN for Apple Push Notification service; FCM for Firebase Cloud Messaging.
                Allowed values: `APN`, `FCM`.
            version: Deprecated. Legacy alias of appVersion; use appVersion. The canonical field takes precedence if both are present.

        Example::

            for device in client.persons.devices.update(42, "abc123", type_="FCM"):
                print(device.app_version)
        """
        if version is not UNSET:
            _warn_deprecated('version', '')
        return _t.cast(_t.List[models.Device], self._call('PUT', f"/persons/{_seg(person_id)}/devices/{_seg(device_id)}", [], _body({'appVersion': app_version, 'pushId': push_id, 'type': type_, 'version': version}, extra_body), _t.List[models.Device], envelope=True))


