class WikiCategoriesResource(Resource):
    """`client.wiki.categories`"""

    def __init__(self, core: _t.Any) -> None:
        super().__init__(core)
        self.pages = WikiCategoriesPagesResource(core)

    def create(
        self,
        *,
        file_access_without_permission: bool,
        in_menu: bool,
        name: str,
        sort_key: int,
        campus_id: _t.Union[_t.Optional[int], UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.WikiCategory:
        """
        Create a new wiki category

        `POST /wiki/categories`

        Creates a wiki category and an initial page titled main (version 1, empty text, Markdown enabled). Requires churchwiki edit masterdata. The creator receives view category and edit category permissions for the new category if missing. A nonexistent campusId silently resolves to null. The returned category has an empty permissions object; use the list to obtain page-operation hints.

        Args:
            campus_id: Optional campus association. Omission/null clears it; an unknown ID currently also resolves to no campus.
            file_access_without_permission: Whether files in this wiki category can be read without category-view permission. This flag does not make the wiki pages themselves public.
            in_menu: Whether the category should appear in navigation menus; it is still returned by the category catalog when false.
            name: Category name; unlike page titles it is not trimmed.
            sort_key: Sort order; negative values are accepted.

        Example::

            result = client.wiki.categories.create(
                file_access_without_permission=False,
                in_menu=True,
                name="Dokumentation",
                sort_key=10,
            )
            print(result.name)
        """
        return _t.cast(models.WikiCategory, self._call('POST', "/wiki/categories", [], _body({'campusId': campus_id, 'fileAccessWithoutPermission': file_access_without_permission, 'inMenu': in_menu, 'name': name, 'sortKey': sort_key}, extra_body), models.WikiCategory, envelope=True))

    def delete(
        self,
        wiki_category_id: int,
    ) -> None:
        """
        Delete a wiki category

        `DELETE /wiki/categories/{wikiCategoryId}`

        Deletes the category, all its wiki page versions and category view/edit permission assignments. Requires churchwiki edit masterdata. Existing pages do not block this deletion, and no page-level protected-system-page check is made by this handler. A missing category normally succeeds with 204. No request body or dry-run parameter is consumed.

        Args:
            wiki_category_id: ID of WikiCategory

        Example::

            client.wiki.categories.delete(42)
        """
        self._raw('DELETE', f"/wiki/categories/{_seg(wiki_category_id)}", [], None)

    def list(
        self,
    ) -> _t.List[models.WikiCategory]:
        """
        Get all wiki categories

        `GET /wiki/categories`

        Lists wiki categories for which the current user (including a guest) has churchwiki view category permission. Categories organize pages and define their access permissions. Results are sorted by sortKey, then stored name, without pagination. inMenu does not filter this catalog. Each category’s canEdit/canDelete flags describe page operations based on edit category, not permission to rename or delete the category itself. The top-level permissions.editMasterData flag controls category administration. meta.count counts visible categories.

        Example::

            for category in client.wiki.categories.list():
                print(category.name)
        """
        return _t.cast(_t.List[models.WikiCategory], self._call('GET', "/wiki/categories", [], None, _t.List[models.WikiCategory], envelope=True))

    def update(
        self,
        wiki_category_id: int,
        *,
        file_access_without_permission: bool,
        in_menu: bool,
        name: str,
        sort_key: int,
        campus_id: _t.Union[_t.Optional[int], UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.WikiCategory:
        """
        Update a wiki category

        `PUT /wiki/categories/{wikiCategoryId}`

        Replaces the category’s name, sort order, menu flag, file-access flag and optional campus association. Requires churchwiki edit masterdata. name, sortKey, inMenu and fileAccessWithoutPermission are required; omitted/null or unknown campusId clears the association. Pages and their versions are retained. The response permissions object is normally empty.

        Args:
            wiki_category_id: ID of WikiCategory
            campus_id: Optional campus association. Omission/null clears it; an unknown ID currently also resolves to no campus.
            file_access_without_permission: Whether files in this wiki category can be read without category-view permission. This flag does not make the wiki pages themselves public.
            in_menu: Whether the category should appear in navigation menus; it is still returned by the category catalog when false.
            name: Category name; unlike page titles it is not trimmed.
            sort_key: Sort order; negative values are accepted.

        Example::

            result = client.wiki.categories.update(
                42,
                file_access_without_permission=False,
                in_menu=True,
                name="Dokumentation",
                sort_key=10,
            )
            print(result.name)
        """
        return _t.cast(models.WikiCategory, self._call('PUT', f"/wiki/categories/{_seg(wiki_category_id)}", [], _body({'campusId': campus_id, 'fileAccessWithoutPermission': file_access_without_permission, 'inMenu': in_menu, 'name': name, 'sortKey': sort_key}, extra_body), models.WikiCategory, envelope=True))


