class ChatResource(Resource):
    """`client.chat`"""

    def create(
        self,
        *,
        domain_id: int,
        guid: str,
        prefix: _t.Literal['cte', 'ctg'],
        roomname: str,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.Chat:
        """
        Start new chat

        `POST /chat`

        Starts synchronization of a chat room with Matrix. New rooms have `STARTING` status and record the current user as creator.

        Args:
            domain_id: ID of the group (`ctg`) or service-planning event (`cte`) associated with the room.
            guid: Stable ChurchTools chat identifier, not a Matrix room ID.
            prefix: `ctg` identifies a group and `cte` identifies a service-planning event.
                Allowed values: `cte`, `ctg`.
            roomname: Display name of the room.

        Example::

            result = client.chat.create(
                domain_id=9,
                guid="681F54E3-2EB7-40A4-84F0-EFF8E8F05727",
                prefix="ctg",
                roomname="Technical team",
            )
            print(result.creator)
        """
        return _t.cast(models.Chat, self._call('POST', "/chat", [], _body({'domainId': domain_id, 'guid': guid, 'prefix': prefix, 'roomname': roomname}, extra_body), models.Chat, envelope=True))

    def delete(
        self,
        guid: str,
        *,
        nonce: _t.Optional[str] = None,
    ) -> None:
        """
        Delete a chat

        `DELETE /chat/{guid}`

        Deletes the local chat room record. A missing record is treated as already deleted.

        Args:
            guid: GUID for Entity
            nonce: Synchronization token for central chat service callbacks.

        Example::

            client.chat.delete("681F54E3-2EB7-40A4-84F0-EFF8E8F05727")
        """
        self._raw('DELETE', f"/chat/{_seg(guid)}", _query([('nonce', nonce)]), None)

    def list(
        self,
        *,
        nonce: _t.Optional[str] = None,
    ) -> _t.List[models.Chat]:
        """
        Get all chats

        `GET /chat`

        Returns all chat rooms, or only rooms matching the supplied synchronization token.

        Args:
            nonce: Synchronization token for central chat service callbacks.

        Example::

            for chat in client.chat.list():
                print(chat.creator)
        """
        return _t.cast(_t.List[models.Chat], self._call('GET', "/chat", _query([('nonce', nonce)]), None, _t.List[models.Chat], envelope=True))

    def patch(
        self,
        guid: str,
        *,
        creator: _t.Union[int, UnsetType] = UNSET,
        domain_id: _t.Union[int, UnsetType] = UNSET,
        nonce: _t.Union[str, UnsetType] = UNSET,
        prefix: _t.Union[_t.Literal['cte', 'ctg'], UnsetType] = UNSET,
        roomname: _t.Union[str, UnsetType] = UNSET,
        status: _t.Union[_t.Literal['STARTED', 'STOPPED'], UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.Chat:
        """
        Update a chat

        `PATCH /chat/{guid}`

        Updates chat room metadata or requests a lifecycle transition.

        Args:
            guid: GUID for Entity
            creator: Person ID recorded as the room creator.
            domain_id: ID of the group (`ctg`) or service-planning event (`cte`) associated with the room.
            nonce: Synchronization token for central chat service callbacks.
            prefix: `ctg` identifies a group and `cte` identifies a service-planning event.
                Allowed values: `cte`, `ctg`.
            roomname: Display name of the room.
            status: Requested lifecycle status.
                Allowed values: `STARTED`, `STOPPED`.

        Example::

            result = client.chat.patch("681F54E3-2EB7-40A4-84F0-EFF8E8F05727", creator=1)
            print(result.creator)
        """
        return _t.cast(models.Chat, self._call('PATCH', f"/chat/{_seg(guid)}", [], _body({'creator': creator, 'domainId': domain_id, 'nonce': nonce, 'prefix': prefix, 'roomname': roomname, 'status': status}, extra_body), models.Chat, envelope=True))


class CheckinResource(Resource):
    """`client.checkin`"""

    def create_persons(
        self,
        *,
        group: models.CheckinMembershipCreate,
        person: models.CheckinPersonDataCreate,
        without_privacy_policy_agreement: _t.Optional[bool] = None,
        tag_id: _t.Union[_t.Optional[int], UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.CheckinPerson:
        """
        Create new person and add to group

        `POST /checkin/persons`

        Creates a person and admits them to a group for the check-in workflow. Requires administer persons, or create person in churchcheckin plus group meeting permission and a person security level covering the selected status. Masterdata IDs are installation-specific. Ordinary duplicate-person confirmation is bypassed; a unique GUID and license limits still apply. A creation note and optional tag are saved before the membership. This request does not record meeting attendance or print a label; perform the actual check-in separately. Failure can leave earlier steps saved because the whole workflow is not one transaction. The response is the legacy person model, not the regular Person representation.

        Args:
            without_privacy_policy_agreement: Omits the otherwise mandatory privacy policy agreement fields. Only effective when `privacy_policy_fields_mandatory_api` is disabled in the ChurchTools configuration. Clients must verify that configuration before using this parameter and must not use it as a fallback for missing agreement information.
            group: Membership to create before a separate attendance check-in. The group’s default role and normal active membership status are used; the origin is check-in. No meeting attendance or label printing is performed here.
            person: Person fields for creation during check-in admission. Uses the normal new-person field validation, including installation-specific masterdata and custom fields. Unlike ordinary creation, this flow forces duplicate creation and ignores visibility. Optional fields depend on configured field security and new-person settings.
            tag_id: Optional person-tag ID. Omitted/null behaves as 0 and normally adds no tag. Nonexistent IDs are silently ignored; use a tag belonging to the person domain.

        Example::

            result = client.checkin.create_persons(
                group=ct.models.CheckinMembershipCreate.model_validate({"id": 9, "personFields": {}}),
                person=ct.models.CheckinPersonDataCreate.model_validate({"campusId": 42, "departmentIds": [42], "firstName": "Alex", "lastName": "Example", "statusId": 42}),
            )
            print(result.first_name)
        """
        return _t.cast(models.CheckinPerson, self._call('POST', "/checkin/persons", _query([('without_privacy_policy_agreement', without_privacy_policy_agreement)]), _body({'group': group, 'person': person, 'tagId': tag_id}, extra_body), models.CheckinPerson, envelope=True))

    def update_persons(
        self,
        *,
        group: models.CheckinMembershipCreate,
        person_id: int,
        tag_id: _t.Union[_t.Optional[int], UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.CheckinPerson:
        """
        Put existing person into group

        `PUT /checkin/persons`

        Admits an existing person to a group using its default role and check-in membership origin, optionally adds a tag, and updates person fields configured for that group. Requires administer persons or group meeting permission. Existing membership is a conflict, not an idempotent success. The operation does not record attendance or print labels. Tag changes occur before membership creation and can remain after a failed request. The returned legacy person-model representation differs from the regular Person API.

        Args:
            group: Membership to create before a separate attendance check-in. The group’s default role and normal active membership status are used; the origin is check-in. No meeting attendance or label printing is performed here.
            person_id: Existing person to admit to the group. A current membership causes a conflict instead of being updated.
            tag_id: Optional person-tag ID. Omitted/null behaves as 0 and normally adds no tag. Nonexistent IDs are silently ignored; use a tag belonging to the person domain.

        Example::

            result = client.checkin.update_persons(
                group=ct.models.CheckinMembershipCreate.model_validate({"id": 9, "personFields": {}}),
                person_id=42,
            )
            print(result.first_name)
        """
        return _t.cast(models.CheckinPerson, self._call('PUT', "/checkin/persons", [], _body({'group': group, 'personId': person_id, 'tagId': tag_id}, extra_body), models.CheckinPerson, envelope=True))


