class EventsResource(Resource):
    """`client.events`"""

    def __init__(self, core: _t.Any) -> None:
        super().__init__(core)
        self.agenda = EventsAgendaResource(core)
        self.eventservices = EventsEventservicesResource(core)
        self.facts = EventsFactsResource(core)
        self.servicerequests = EventsServicerequestsResource(core)
        self.services = EventsServicesResource(core)

    def chat(
        self,
        event_id: int,
        *,
        enabled: bool,
        trigger_chat_invite_mail: _t.Union[bool, UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> None:
        """
        Start or stop an event chat

        `POST /events/{eventId}/chat`

        Starts, reactivates or stops the chat linked to this event. Requires access to the event, an active chat installation with event chats enabled, and permission to administer persons, start an event chat through event permissions, or administer this event. A new room is provisioned through the chat service; HTTP `200` does not guarantee that remote room setup is already complete. Stopping a chat that has never been created returns `404`.

        Args:
            event_id: ID of Event
            enabled: `true` starts or reactivates the event chat; `false` stops an existing chat.
            trigger_chat_invite_mail: Send invitations to eligible event participants who cannot chat yet. This is independent of enabled: `true` can also send invitations when stopping the chat. Repeated requests can send invitations again.

        Example::

            client.events.chat(42, enabled=True)
        """
        self._raw('POST', f"/events/{_seg(event_id)}/chat", [], _body({'enabled': enabled, 'triggerChatInviteMail': trigger_chat_invite_mail}, extra_body))

    def create_ical(
        self,
        *,
        person_id: int,
    ) -> models.RosterICalSetting:
        """
        Create iCal roster link

        `POST /events/ical`

        Creates a new personal roster subscription secret and returns the link as JSON. Use `meta.iCalUrl` to fetch the actual iCalendar feed. A roster contains the person's service assignments at events, including pending requests and confirmed assignments.

        Args:
            person_id: ID of person

        Example::

            result = client.events.create_ical(person_id=42)
            print(result.attribute)
        """
        return _t.cast(models.RosterICalSetting, self._call('POST', "/events/ical", _query([('personId', person_id)]), None, models.RosterICalSetting, envelope=True))

    def delete(
        self,
        event_id: int,
        *,
        dry_run: _t.Optional[bool] = None,
        send_mail: _t.Optional[bool] = None,
    ) -> None:
        """
        Delete a single event

        `DELETE /events/{eventId}`

        Deletes the service-planning event through the dependency-aware deletion service. With `dryRun`=`true`, the deletion check returns a `409` report without deleting the event, but `sendMail` is processed before that check. Requires event administration access, the "edit events" permission for the event calendar, or a corresponding internal group permission.

        Args:
            event_id: ID of Event
            dry_run: Check deletion and return a `409` report. Does not suppress the `sendMail` step.
            send_mail: Request event-deletion notifications before the deletion check, including during `dryRun`.

        Example::

            client.events.delete(42)
        """
        self._raw('DELETE', f"/events/{_seg(event_id)}", _query([('dryRun', dry_run), ('sendMail', send_mail)]), None)

    def get(
        self,
        event_id: int,
    ) -> models.EventReadWithServices:
        """
        Get a single event

        `GET /events/{eventId}`

        Returns the event visible to the current user, including calendar, eventFiles and eventServices. Service assignments are filtered by service-group visibility or own assignment; persons can be concealed. The eventServices property is present even when empty. Cancelled events can also be read if visible.

        Args:
            event_id: ID of Event

        Example::

            event = client.events.get(42)
            print(event.name)
        """
        return _t.cast(models.EventReadWithServices, self._call('GET', f"/events/{_seg(event_id)}", [], None, models.EventReadWithServices, envelope=True))

    def get_ical(
        self,
        *,
        person_id: int,
    ) -> models.RosterICalSetting:
        """
        Get iCal roster link

        `GET /events/ical`

        Returns the personal roster subscription as JSON. If no secret exists, this `GET` creates one; otherwise it preserves the existing link. Use `meta.iCalUrl` to fetch the actual iCalendar feed. A roster contains the person's service assignments at events, including pending requests and confirmed assignments.

        Args:
            person_id: ID of person

        Example::

            ical = client.events.get_ical(person_id=42)
            print(ical.attribute)
        """
        return _t.cast(models.RosterICalSetting, self._call('GET', "/events/ical", _query([('personId', person_id)]), None, models.RosterICalSetting, envelope=True))

    def list(
        self,
        *,
        from_: _t.Optional[_dt.date] = None,
        to: _t.Optional[_dt.date] = None,
        direction: _t.Optional[_t.Literal['backward', 'forward']] = None,
        limit: _t.Optional[int] = None,
        canceled: _t.Optional[bool] = None,
        include: _t.Optional[str] = None,
    ) -> Paginator[models.Event]:
        """
        Get all events

        `GET /events`

        Returns events visible through calendar permissions or the current user’s valid service assignments. Date comparisons use midnight in the application time zone: to includes exactly midnight, not later events that day. Results from calendar access are merged with events where the user is assigned and deduplicated; this merged range list is not guaranteed to be globally sorted. With direction, selects one page relative to from and ignores to.

        Args:
            from_: Midnight anchor or beginning of the range.
            to: Range upper bound at midnight, inclusive.
            direction: Enable directional pagination; omit for an unpaginated date range.
                Allowed values: `backward`, `forward`.
            limit: Results per page in directional mode; ignored in range mode.
            canceled: Include cancelled events in addition to active events.
            include: Comma-separated Fractal includes. event_services includes visible assignments; eventServices is its legacy spelling. The response key follows the selected spelling. Other Fractal syntax is accepted, so this is not a closed enum.

        Example::

            for event in client.events.list():
                print(event.name)
        """
        return Paginator(self._core, "/events", _query([('from', from_), ('to', to), ('direction', direction), ('limit', limit), ('canceled', canceled), ('include', include)]), models.Event)

    def list_possiblepersonsforservice(
        self,
        service_id: int,
    ) -> _t.List[models.ServiceCandidate]:
        """
        Get all possible persons for a service

        `GET /events/{serviceId}/possiblepersonsforservice`

        Returns an unpaginated, deduplicated list of persons from active, non-hidden memberships in groups connected to the service. If connected tags exist, a matching tag is also required. Archived or deceased persons are excluded and hidden-person visibility is respected. With no connected groups, the result is empty.

        Args:
            service_id: ID of a reusable service role from /services

        Example::

            for possiblepersonsforservice in client.events.list_possiblepersonsforservice(2):
                print(possiblepersonsforservice.full_name)
        """
        return _t.cast(_t.List[models.ServiceCandidate], self._call('GET', f"/events/{_seg(service_id)}/possiblepersonsforservice", [], None, _t.List[models.ServiceCandidate], envelope=True))

    def send(
        self,
        *,
        body: str,
        event_ids: _t.List[int],
        recipients: _t.List[int],
        subject: str,
        append_agenda_button: bool,
        files: _t.List[int],
        send_copy_to_me: _t.Union[bool, UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.EventMailSendResult:
        """
        Send an email to selected event recipients

        `POST /events/send`

        Sends an email to selected people in the context of one or more events. ChurchTools filters service participants by visible service groups and other selected recipients by person visibility. The response reports effective and rejected recipients. `sendCopyToMe` can add the sender. Optional agenda buttons require agenda visibility for each event; sending does not require an agenda or a shared agenda across events.

        Args:
            body: HTML email body. ChurchTools appends buttons for all supplied events and any requested, available agenda and file links.
            event_ids: Events used to resolve participating recipients and message links. Every supplied event must exist. Events are not required to share an agenda.
            recipients: Selected person IDs. Only selected participants in visible service groups of the loaded events, or selected people the sender may otherwise view, receive the message. The response reports other IDs as rejected. Participants are not added automatically.
            send_copy_to_me: Also include the currently logged-in person as a recipient, even if their ID is absent from recipients.
            subject: Email subject.
            append_agenda_button: Append links for supplied events that have an agenda and for whose calendar the sender has "view agenda" permission.
            files: File IDs to list as links in the message body. Only files associated with one of the supplied events are used. These are links, not binary email attachments.

        Example::

            event = client.events.send(
                body="<p>Please review the updated agenda for Sunday.</p>",
                event_ids=[31, 32],
                recipients=[40, 41],
                subject="Updated Sunday agenda",
                append_agenda_button=True,
                files=[42],
            )
            print(event)
        """
        return _t.cast(models.EventMailSendResult, self._call('POST', "/events/send", [], _body({'body': body, 'eventIds': event_ids, 'recipients': recipients, 'sendCopyToMe': send_copy_to_me, 'subject': subject, 'appendAgendaButton': append_agenda_button, 'files': files}, extra_body), models.EventMailSendResult, envelope=True))

    def update(
        self,
        event_id: int,
        *,
        admin_ids: _t.Union[_t.List[int], UnsetType] = UNSET,
        description: _t.Union[_t.Optional[str], UnsetType] = UNSET,
        event_admin_ids: _t.Union[_t.List[int], UnsetType] = UNSET,
        is_canceled: _t.Union[bool, UnsetType] = UNSET,
        note: _t.Union[_t.Optional[str], UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.EventDetailsUpdateResult:
        """
        Update event details

        `PUT /events/{eventId}`

        Updates the description, administrators and cancellation state for this service-planning event. It does not update service assignments or the calendar appointment. Changing the administrator set additionally requires the "edit masterdata" permission for the service planning domain; other changes require event administration access, the "edit events" permission for the event calendar, or a corresponding internal group permission.

        Args:
            event_id: ID of Event
            admin_ids: Replace the administrator list. A change to the set of IDs additionally requires the "edit masterdata" permission for the service planning domain.
            description: Event description.
            event_admin_ids: Deprecated. Legacy input alias for `adminIds`.
            is_canceled: Whether the service-planning event is cancelled.
            note: Deprecated. Deprecated alias for `description`.

        Example::

            result = client.events.update(
                42,
                description="Sound check starts 30 minutes before the gathering.",
            )
            print(result.id)
        """
        if event_admin_ids is not UNSET:
            _warn_deprecated('event_admin_ids', '')
        if note is not UNSET:
            _warn_deprecated('note', '')
        return _t.cast(models.EventDetailsUpdateResult, self._call('PUT', f"/events/{_seg(event_id)}", [], _body({'adminIds': admin_ids, 'description': description, 'eventAdminIds': event_admin_ids, 'isCanceled': is_canceled, 'note': note}, extra_body), models.EventDetailsUpdateResult, envelope=True))


