class FinanceResource(Resource):
    """`client.finance`"""

    def __init__(self, core: _t.Any) -> None:
        super().__init__(core)
        self.accountclasses = FinanceAccountclassesResource(core)
        self.accountgroups = FinanceAccountgroupsResource(core)
        self.accountingperiods = FinanceAccountingperiodsResource(core)
        self.accounts = FinanceAccountsResource(core)
        self.accounttypes = FinanceAccounttypesResource(core)
        self.bills = FinanceBillsResource(core)
        self.cashdiscounts = FinanceCashdiscountsResource(core)
        self.clients = FinanceClientsResource(core)
        self.costcenters = FinanceCostcentersResource(core)
        self.donators = FinanceDonatorsResource(core)
        self.eubp = FinanceEubpResource(core)
        self.reports = FinanceReportsResource(core)
        self.splittransactions = FinanceSplittransactionsResource(core)
        self.taxrates = FinanceTaxratesResource(core)
        self.taxtypes = FinanceTaxtypesResource(core)
        self.templates = FinanceTemplatesResource(core)
        self.transactionpurposes = FinanceTransactionpurposesResource(core)
        self.transactions = FinanceTransactionsResource(core)

    def get_masterdata(
        self,
        *,
        accounting_period_id: int,
    ) -> models.FinanceMasterData:
        """
        Get finance master data for an accounting period

        `GET /finance/masterdata`

        Finance definitions needed for one accounting period. Clients and periods include all entries visible to the caller; account types, classes, groups and tax types are installation-wide. Accounts, cost centers, tax rates, cash discounts and transaction purposes relate to the selected period. The selected accounting period must be visible. Returns data, per-collection counts in meta and top-level UI permissions. Account balances are calculated only with global view/edit accounting period permission; otherwise account values may remain at their uncalculated defaults. Cost-center budgets are calculated independently. Unlike /finance/transactionpurposes, the preset list is restricted by period and, without global period rights, by groups allowing posting.

        Args:
            accounting_period_id: Visible accounting period whose finance definitions are requested.

        Example::

            masterdata = client.finance.get_masterdata(accounting_period_id=1)
            print(masterdata)
        """
        return _t.cast(models.FinanceMasterData, self._call('GET', "/finance/masterdata", _query([('accounting_period_id', accounting_period_id)]), None, models.FinanceMasterData, envelope=True))


class FollowupsResource(Resource):
    """`client.followups`"""

    def complete(
        self,
        follow_up_id: int,
        *,
        success_group_id: _t.Union[_t.Optional[int], UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.FollowUp2:
        """
        Complete follow-up

        `POST /followups/{followUpId}/complete`

        Sets `doneDate` to the current timestamp and records completion history. The subject person must be visible. Group-associated follow-ups require "churchdb +do followup" permission in that group. A supplied nonzero `successGroupId` adds or updates the subject’s membership in that selected group, including overwriting an existing membership’s role/status. Configured fixed-group/group-type restrictions are checked; a configured group is not selected automatically. Emits a completion event, which can trigger configured continuations or routines. Repeating this operation replaces `doneDate`, writes another history entry and emits another event. Due dates are retained.

        Args:
            follow_up_id: ID of Follow-up
            success_group_id: Selected destination group. Must match a configured fixed group and/or group-type restriction. Completion can create or overwrite this person’s membership using the configured role/status defaults.

        Example::

            followup = client.followups.complete(2, success_group_id=42)
            print(followup.title)
        """
        return _t.cast(models.FollowUp2, self._call('POST', f"/followups/{_seg(follow_up_id)}/complete", [], _body({'successGroupId': success_group_id}, extra_body), models.FollowUp2, envelope=True))

    def delete(
        self,
        follow_up_id: int,
    ) -> None:
        """
        Delete follow-up

        `DELETE /followups/{followUpId}`

        Deletes the follow-up and records deletion history in a transaction. Its specification is also deleted when it is not shared; a shared specification remains. Deletion requires access to the subject person and, for a group-associated follow-up, follow-up administration rights in that group. No dryRun/dependency-preview behavior is implemented. This removes the follow-up rather than marking it finished; it does not reverse group memberships or routine effects caused by earlier completion.

        Args:
            follow_up_id: ID of Follow-up

        Example::

            client.followups.delete(2)
        """
        self._raw('DELETE', f"/followups/{_seg(follow_up_id)}", [], None)

    def dismiss(
        self,
        follow_up_id: int,
        *,
        body: _t.Optional[StrMap[_t.Any]] = None,
    ) -> models.FollowUp2:
        """
        Dismiss follow-up

        `POST /followups/{followUpId}/dismiss`

        Marks the follow-up as finished by setting `doneDate` to the current timestamp and recording a dismissal history entry. The subject person must be visible. Group-associated follow-ups require "churchdb +do followup" permission in that group. No success-group membership is changed and no completion event is emitted. Completion and dismissal both appear through `doneDate` and differ only in history. Repeating dismissal updates `doneDate` and creates another history entry.

        Args:
            follow_up_id: ID of Follow-up

        Example::

            followup = client.followups.dismiss(2)
            print(followup.title)
        """
        return _t.cast(models.FollowUp2, self._call('POST', f"/followups/{_seg(follow_up_id)}/dismiss", [], _body(body), models.FollowUp2, envelope=True))

    def get(
        self,
        follow_up_id: int,
    ) -> models.FollowUp2:
        """
        Get follow-up

        `GET /followups/{followUpId}`

        Returns one follow-up, including its subject person/group context, responsible person, current/original due dates and configured completion group. The current owner may view it; a group-associated follow-up is also visible to users with that group’s follow-up execution or administration rights. This direct check is broader than the list selection: group follow-ups assigned to another person can be read by eligible group staff even when omitted from their list. The response does not include notes or history, nor indicate whether its underlying specification is shared.

        Args:
            follow_up_id: ID of Follow-up

        Example::

            followup = client.followups.get(2)
            print(followup.title)
        """
        return _t.cast(models.FollowUp2, self._call('GET', f"/followups/{_seg(follow_up_id)}", [], None, models.FollowUp2, envelope=True))

    def list(
        self,
        *,
        filter: _t.Optional[_t.List[_t.Literal['done', 'due-after-today', 'due-before-today', 'due-today', 'due-unspecified']]] = None,
        limit: _t.Optional[int] = None,
    ) -> Paginator[models.FollowUp2]:
        """
        List follow-ups assigned to the current user or eligible groups

        `GET /followups`

        Returns follow-ups owned by the current user plus unassigned group follow-ups for groups where the user has follow-up execution or administration rights. This includes personal and membership follow-ups; it is not an unrestricted list of every follow-up for a visible person. Archived subject persons are excluded. Date filters use `effectiveDueDate` and are combined with OR. Results are sorted by doneDate descending, then effectiveDueDate ascending, then ID ascending; finished items can precede open ones. Page/limit slice the result, but meta only contains count for this page, without a total or last page.

        Args:
            filter: Repeat to select any of the listed states. An empty array includes all states.
                Allowed values: `done`, `due-after-today`, `due-before-today`, `due-today`, `due-unspecified`.
            limit: Maximum results in this page.

        Example::

            for followup in client.followups.list():
                print(followup.title)
        """
        return Paginator(self._core, "/followups", _query([('filter[]', filter), ('limit', limit)]), models.FollowUp2)

    def notes(
        self,
        follow_up_id: int,
        *,
        comment: str,
        also_apply_to_person: _t.Optional[bool] = None,
        comment_viewer_id: _t.Union[_t.Optional[int], UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> None:
        """
        Add a note to a follow-up

        `POST /followups/{followUpId}/notes`

        Creates a note linked to this follow-up. With `also_apply_to_person=true`, the same note is also linked to the subject person. `commentViewerId` applies only to the person link. The subject person must be visible; group-associated follow-ups require "churchdb +do followup" permission in that group.

        Args:
            follow_up_id: ID of Follow-up
            also_apply_to_person: Additionally link the same note to the subject person.
            comment: Note text.
            comment_viewer_id: Visibility category applied only to an additional person link when `also_apply_to_person=true`. Ignored for the follow-up link itself.

        Example::

            client.followups.notes(
                2,
                comment="Called Alex; another conversation is planned for next week.",
            )
        """
        self._raw('POST', f"/followups/{_seg(follow_up_id)}/notes", _query([('also_apply_to_person', also_apply_to_person)]), _body({'comment': comment, 'commentViewerId': comment_viewer_id}, extra_body))

    def postpone(
        self,
        follow_up_id: int,
        *,
        due_date: _dt.date,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.FollowUp2:
        """
        Postpone follow-up

        `POST /followups/{followUpId}/postpone`

        Changes `effectiveDueDate` to a future calendar date and records postponement history. `dueDate` remains the original plan. The subject person must be visible. Group-associated follow-ups require "churchdb +do followup" permission in that group. Today is rejected. The method does not clear `doneDate` or reject already-finished follow-ups, so use reset to reopen one. No completion event or success-group action is performed.

        Args:
            follow_up_id: ID of Follow-up
            due_date: New effective date, strictly after today in server date handling. The original `dueDate` is retained.

        Example::

            followup = client.followups.postpone(2, due_date=dt.date(2026, 12, 1))
            print(followup.title)
        """
        return _t.cast(models.FollowUp2, self._call('POST', f"/followups/{_seg(follow_up_id)}/postpone", [], _body({'dueDate': due_date}, extra_body), models.FollowUp2, envelope=True))

    def reset(
        self,
        follow_up_id: int,
        *,
        due_date: _t.Union[_t.Optional[_dt.date], UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.FollowUp2:
        """
        Reset follow-up

        `POST /followups/{followUpId}/reset`

        Reopens the follow-up by clearing `doneDate` and records reset history. A supplied future `dueDate` becomes `effectiveDueDate`; otherwise the original `dueDate` is restored as the effective date. The original `dueDate` is unchanged. The subject person must be visible. Group-associated follow-ups require "churchdb +do followup" permission in that group. Reset is also accepted for an already-open follow-up. It does not undo previous completion effects.

        Args:
            follow_up_id: ID of Follow-up
            due_date: A future date overrides `effectiveDueDate`; otherwise it is restored from the original `dueDate`, which may be past or null.

        Example::

            followup = client.followups.reset(2, due_date=dt.date(2026, 12, 1))
            print(followup.title)
        """
        return _t.cast(models.FollowUp2, self._call('POST', f"/followups/{_seg(follow_up_id)}/reset", [], _body({'dueDate': due_date}, extra_body), models.FollowUp2, envelope=True))

    def update(
        self,
        follow_up_id: int,
        *,
        body: _t.Union[models.FollowUpUpdate, models.FollowUpSharedUpdate],
    ) -> models.FollowUp2:
        """
        Update follow-up

        `PUT /followups/{followUpId}`

        Updates mutable fields of the specified follow-up.

        Args:
            follow_up_id: ID of Follow-up

        Example::

            result = client.followups.update(
                2,
                body=ct.models.FollowUpUpdate.model_validate({"title": "Call Peter"}),
            )
            print(result.title)
        """
        return _t.cast(models.FollowUp2, self._call('PUT', f"/followups/{_seg(follow_up_id)}", [], _body(body), models.FollowUp2, envelope=True))


