class NotesResource(Resource):
    """`client.notes`"""

    def create(
        self,
        domain_type: _t.Literal['follow_up', 'group', 'person', 'song_arrangement'],
        domain_id: int,
        *,
        text: str,
        comment_viewer_id: _t.Union[_t.Optional[int], UnsetType] = UNSET,
        security_level_id: _t.Union[_t.Optional[int], UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.Note:
        """
        Create a note attached to an object

        `POST /notes/{domainType}/{domainId}`

        Creates a note linked to the object in the URL. Group notes require an existing group and group-note editing rights. Arrangement notes require "edit songcategory" permission for the parent song’s category. Person notes require person visibility, permission for the selected comment-viewer category, and person write or applicable group-member field-edit permission. Direct creation for `follow_up` is rejected; use the follow-up note API.

        Args:
            domain_type: Domain types that notes can be used with
                Allowed values: `follow_up`, `group`, `person`, `song_arrangement`.
            domain_id: the domain id
            comment_viewer_id: Visibility category for person notes. Creating a person note requires permission for this category.
            security_level_id: Group-note security threshold; ignored for list filtering in the other domains. The create handler also accepts legacy string representations.
            text: Note content shared by all links.

        Example::

            result = client.notes.create("group", 35, text="Please follow up next week.")
            print(result.id)
        """
        return _t.cast(models.Note, self._call('POST', f"/notes/{_seg(domain_type)}/{_seg(domain_id)}", [], _body({'commentViewerId': comment_viewer_id, 'securityLevelId': security_level_id, 'text': text}, extra_body), models.Note, envelope=True))

    def delete(
        self,
        note_id: int,
    ) -> None:
        """
        Delete a note and all its links

        `DELETE /notes/{noteId}`

        Deletes the note from every linked business object. Authors can delete their notes without a fresh object-access check. Non-authors need global `churchdb` write access, and the first stored link must be a person link; person and comment visibility are not checked. Other domains do not allow non-author deletion. `DELETE /notes/{domainType}/{domainId}/{noteId}` is an equivalent alias whose domain path fields are ignored.

        Args:
            note_id: ID of note

        Example::

            client.notes.delete(101)
        """
        self._raw('DELETE', f"/notes/{_seg(note_id)}", [], None)

    def delete_for_object(
        self,
        domain_type: str,
        domain_id: str,
        note_id: int,
    ) -> None:
        """
        Delete a note and all its links

        `DELETE /notes/{domainType}/{domainId}/{noteId}`

        Deletes the note and all its links, not only the link named in the URL. The handler ignores `domainType` and `domainId`. Authors can delete their notes without a fresh domain-access check. Non-authors need global `churchdb` write access, and the first stored link must be a person link; person and comment visibility are not checked. Other domains do not allow non-author deletion. `DELETE /notes/{noteId}` calls the same handler.

        Args:
            domain_type: Legacy path context; ignored by this DELETE handler.
            domain_id: Legacy object identifier; ignored by this DELETE handler.
            note_id: ID of note

        Example::

            client.notes.delete_for_object("group", "42", 101)
        """
        self._raw('DELETE', f"/notes/{_seg(domain_type)}/{_seg(domain_id)}/{_seg(note_id)}", [], None)

    def get(
        self,
        domain_type: _t.Literal['follow_up', 'group', 'person', 'song_arrangement'],
        domain_id: int,
    ) -> _t.List[models.Note]:
        """
        List visible notes attached to an object

        `GET /notes/{domainType}/{domainId}`

        Lists notes linked to the requested object, newest creation date first, without pagination. Group notes require group visibility and a sufficient security level, person notes require comment-viewer permission, arrangement notes require parent-song visibility, and follow-up notes require access to the follow-up. Authors bypass the group security-level or person comment-category filter after the initial domain check. Person notes do not check the requested person’s visibility or existence. Each note includes all links and uses its first stored link for top-level domain fields.

        Args:
            domain_type: Domain types that notes can be used with
                Allowed values: `follow_up`, `group`, `person`, `song_arrangement`.
            domain_id: the domain id

        Example::

            for note in client.notes.get("group", 35):
                print(note.id)
        """
        return _t.cast(_t.List[models.Note], self._call('GET', f"/notes/{_seg(domain_type)}/{_seg(domain_id)}", [], None, _t.List[models.Note], envelope=True))

    def update(
        self,
        domain_type: _t.Literal['follow_up', 'group', 'person', 'song_arrangement'],
        domain_id: int,
        note_id: int,
        *,
        text: str,
        comment_viewer_id: _t.Union[_t.Optional[int], UnsetType] = UNSET,
        security_level_id: _t.Union[_t.Optional[int], UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.Note:
        """
        Replace an authored note’s text and visibility

        `PUT /notes/{domainType}/{domainId}/{noteId}`

        Updates a note owned by the current author. Only `noteId` selects the note; `domainId` does not verify its association. The shared text changes for every linked context, while visibility changes only on the first link matching `domainType`. No fresh domain or comment-category permission check is performed.

        Args:
            domain_type: Domain types that notes can be used with
                Allowed values: `follow_up`, `group`, `person`, `song_arrangement`.
            domain_id: the domain id
            note_id: ID of note
            comment_viewer_id: Person-comment visibility category. The update handler does not repeat the category permission check used on create.
            security_level_id: Group-note security level. Unlike create, the update does not accept legacy string representations.
            text: Note content shared by all links.

        Example::

            result = client.notes.update("group", 35, 101, text="Please follow up next week.")
            print(result.id)
        """
        return _t.cast(models.Note, self._call('PUT', f"/notes/{_seg(domain_type)}/{_seg(domain_id)}/{_seg(note_id)}", [], _body({'commentViewerId': comment_viewer_id, 'securityLevelId': security_level_id, 'text': text}, extra_body), models.Note, envelope=True))


