class RegistrationsResource(Resource):
    """`client.registrations`"""

    def confirm(
        self,
        registration_guid: str,
        *,
        token: str,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.Registration:
        """
        Confirm self-registration email

        `POST /registrations/{registrationGuid}/confirm`

        Verifies the emailed token for an unconverted registration and records the confirmation time. Returns active persons with the same default email as `possibleMatches`, including configured form fields and `hasPassword`. Repeated confirmation is accepted while the registration is unconverted.

        Args:
            registration_guid: GUID of the pending self-registration
            token: Confirmation token from the emailed link.

        Example::

            registration = client.registrations.confirm("8c3bf5f0-305d-4e24-8e06-7c1d217fd3f1", token="abc123")
            print(registration.first_name)
        """
        return _t.cast(models.Registration, self._call('POST', f"/registrations/{_seg(registration_guid)}/confirm", [], _body({'token': token}, extra_body), models.Registration, envelope=True))

    def convert(
        self,
        registration_guid: str,
        *,
        form_data: models.RegistrationConvertFormData,
        token: str,
        person_id: _t.Union[int, UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> None:
        """
        Complete self-registration

        `POST /registrations/{registrationGuid}/convert`

        Completes an email-confirmed, unconverted registration using its token. Creates a new person or links `personId` to an active person with the same default email. Requires an active/complete configuration and enabled default login. `formData` supplies consent and configured fields by field ID or modern person field name (ID takes precedence); unknown/unconfigured fields are discarded. Required configured fields and person data are validated. A new person receives configured status, departments, tags and campus group memberships; a sole campus is selected automatically, otherwise `formData.campusId` must match a configured campus. Existing persons receive supplied fields, configured existing-person tags and the registration password. Success marks conversion complete and logs in that person in the current session.

        Args:
            registration_guid: GUID of the pending self-registration
            form_data: Consent fields plus configured person fields by numeric field ID or modern field name.
            person_id: Eligible existing person to link; without it, a new person is created.
            token: Same token used for email confirmation.

        Example::

            client.registrations.convert(
                "8c3bf5f0-305d-4e24-8e06-7c1d217fd3f1",
                form_data=ct.models.RegistrationConvertFormData.model_validate({"acceptDataPrivacy": True}),
                token="abc123",
            )
        """
        self._raw('POST', f"/registrations/{_seg(registration_guid)}/convert", [], _body({'formData': form_data, 'personId': person_id, 'token': token}, extra_body))

    def create(
        self,
        *,
        config_id: str,
        email: str,
        first_name: str,
        last_name: str,
        password: str,
        has_minimum_age: _t.Union[bool, UnsetType] = UNSET,
        redirect_after_registration: _t.Union[_t.Optional[str], UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> _t.Optional[models.Registration]:
        """
        Start self-registration

        `POST /registrations`

        Starts account self-registration for the configuration GUID and emails a confirmation link. Requires an active, complete configuration and an enabled default login. Blacklisted email addresses, blocked accounts and recognized existing login accounts receive an informational email and return `204` without creating a registration.

        Args:
            config_id: GUID from `RegistrationConfig.guid`.
            email: Email address used for confirmation.
            first_name: Given name.
            has_minimum_age: Applicant confirms the configured minimum age.
            last_name: Family name.
            password: Must satisfy the configured password-strength requirements.
            redirect_after_registration: Destination for the client after completion.

        Example::

            result = client.registrations.create(
                config_id="8c3bf5f0-305d-4e24-8e06-7c1d217fd3f1",
                email="mara@example.org",
                first_name="Mara",
                last_name="Becker",
                password="geheim",
            )
            print(result)
        """
        return _t.cast(_t.Optional[models.Registration], self._call('POST', "/registrations", [], _body({'configId': config_id, 'email': email, 'firstName': first_name, 'hasMinimumAge': has_minimum_age, 'lastName': last_name, 'password': password, 'redirectAfterRegistration': redirect_after_registration}, extra_body), _t.Optional[models.Registration], envelope=True))

    def delete(
        self,
        registration_guid: str,
    ) -> None:
        """
        Delete self-registration

        `DELETE /registrations/{registrationGuid}`

        Deletes the registration record by GUID. This does not delete a person created by an earlier conversion.

        Args:
            registration_guid: GUID of the pending self-registration

        Example::

            client.registrations.delete("8c3bf5f0-305d-4e24-8e06-7c1d217fd3f1")
        """
        self._raw('DELETE', f"/registrations/{_seg(registration_guid)}", [], None)

    def resend(
        self,
        registration_guid: str,
    ) -> None:
        """
        Resend self-registration confirmation

        `POST /registrations/{registrationGuid}/resend`

        Resends the confirmation email for this registration.

        Args:
            registration_guid: GUID of the pending self-registration

        Example::

            client.registrations.resend("8c3bf5f0-305d-4e24-8e06-7c1d217fd3f1")
        """
        self._raw('POST', f"/registrations/{_seg(registration_guid)}/resend", [], None)


