    def create(
        self,
        *,
        category_id: int,
        name: str,
        author: _t.Union[_t.Optional[str], UnsetType] = UNSET,
        ccli: _t.Union[_t.Optional[str], UnsetType] = UNSET,
        copyright: _t.Union[_t.Optional[str], UnsetType] = UNSET,
        should_practice: _t.Union[bool, UnsetType] = UNSET,
        tags: _t.Union[_t.List[str], UnsetType] = UNSET,
        arrangements: _t.Union[_t.List[models.ArrangementCreate], UnsetType] = UNSET,
        extra_body: _t.Optional[_t.Dict[str, _t.Any]] = None,
    ) -> models.Song:
        """
        Create a new song

        `POST /songs`

        Creates a song in an existing category. Requires edit songcategory permission for that category. Inline arrangements use the same contract as the arrangement creation endpoint, including source and file assignments. The first arrangement becomes the default unless a later item requests that role. The response does not enrich tags.

        Args:
            author: Author or composer credits.
            category_id: ID of an existing song category from GET /song/categories. Categories organize songs and determine access permissions. Changing it requires edit permission for both the old and the new category.
            ccli: CCLI song number, stored as text.
            copyright: Copyright or licensing notice.
            name: Song title.
            should_practice: Marks the song for rehearsal.
            tags: Tag names to assign. Existing tags are reused by name; missing tags are created. During update, this replaces the song's tag set.
            arrangements: Initial musical versions. The first arrangement becomes the default unless a later item has `isDefault: true`.

        Example::

            result = client.songs.create(category_id=1, name="Hallelujah")
            print(result.name)
        """
        return _t.cast(models.Song, self._call('POST', "/songs", [], _body({'author': author, 'categoryId': category_id, 'ccli': ccli, 'copyright': copyright, 'name': name, 'shouldPractice': should_practice, 'tags': tags, 'arrangements': arrangements}, extra_body), models.Song, envelope=True))

    def delete(
        self,
        song_id: int,
    ) -> None:
        """
        Delete song

        `DELETE /songs/{songId}`

        Deletes the song, its tag associations, arrangements and arrangement files. The tags themselves remain available. Requires edit songcategory permission for the song's category. Agenda items referring to deleted arrangements keep their item records but lose the arrangement reference.

        Args:
            song_id: ID of song

        Example::

            client.songs.delete(42)
        """
        self._raw('DELETE', f"/songs/{_seg(song_id)}", [], None)

    def get(
        self,
        song_id: int,
        *,
        include: _t.Optional[_t.List[_t.Literal['arrangements', 'tags']]] = None,
    ) -> models.Song:
        """
        Get song

        `GET /songs/{songId}`

        Returns a song with its category, musical details and all arrangements. Requires view songcategory or edit songcategory permission for its category. Use include=tags to additionally retrieve its tags. Arrangement selection for a particular event belongs to that event's agenda item.

        Args:
            song_id: ID of song
            include: Optional enrichments. Use include=tags for tags, or include[]=tags&include[]=arrangements for multiple values. Comma-separated values are not supported. Arrangements are already returned without this option by the current API, but this will change in a future release. Omitted requests no enrichment.
                Allowed values: `arrangements`, `tags`.

        Example::

            song = client.songs.get(42)
            print(song.name)
        """
        return _t.cast(models.Song, self._call('GET', f"/songs/{_seg(song_id)}", _query([('include[]', include)]), None, models.Song, envelope=True))

    def list(
        self,
        *,
        song_category_ids: _t.Optional[_t.List[int]] = None,
        ids: _t.Optional[_t.List[int]] = None,
        practice: _t.Optional[bool] = None,
        key_of_arrangement: _t.Optional[_t.Literal['A', 'A#', 'A#m', 'Ab', 'Abm', 'Am', 'B', 'B#', 'B#m', 'Bb', 'Bbm', 'Bm', 'C', 'C#', 'C#m', 'Cb', 'Cbm', 'Cm', 'D', 'D#', 'D#m', 'Db', 'Dbm', 'Dm', 'E', 'E#', 'E#m', 'Eb', 'Ebm', 'Em', 'F', 'F#', 'F#m', 'Fb', 'Fbm', 'Fm', 'G', 'G#', 'G#m', 'Gb', 'Gbm', 'Gm']] = None,
        name: _t.Optional[str] = None,
        query: _t.Optional[str] = None,
        include: _t.Optional[_t.List[_t.Literal['arrangements', 'tags']]] = None,
        limit: _t.Optional[int] = None,
    ) -> Paginator[models.Song]:
        """
        Get all songs

        `GET /songs`

        Returns songs in categories for which the caller has view songcategory or edit songcategory permission. Songs are sorted by name, then ID, both ascending. Filters are combined with AND; query matches either title or author. Category filters are intersected with permitted categories. No permitted or matching songs returns an empty list. Each song includes all arrangements, including those that do not match key_of_arrangement. Results are paginated.

        Args:
            song_category_ids: Restrict to these song category IDs, intersected with permitted categories.
            ids: Restrict to these song IDs. An empty array matches no songs.
            practice: Filter the rehearsal flag: `true` selects songs marked for practice, false selects those not marked.
            key_of_arrangement: Filter by arrangement key. Song plus all its arrangements are returned if one arrangement meets the filter criterion.
                Allowed values: `A`, `A#`, `A#m`, `Ab`, `Abm`, `Am`, `B`, `B#`, `B#m`, `Bb`, `Bbm`, `Bm`, `C`, `C#`, `C#m`, `Cb`, `Cbm`, `Cm`, `D`, `D#`, `D#m`, `Db`, `Dbm`, `Dm`, `E`, `E#`, `E#m`, `Eb`, `Ebm`, `Em`, ….
            name: Substring filter on the song title, combined with query and the other filters.
            query: Substring search in either title or author, combined with name and the other filters.
            include: Optional enrichments. Use include=tags for tags, or include[]=tags&include[]=arrangements for multiple values. Comma-separated values are not supported. Arrangements are already returned without this option by the current API, but this will change in a future release. Omitted requests no enrichment.
                Allowed values: `arrangements`, `tags`.
            limit: Number of songs per page, from 1 to 200.

        Example::

            for song in client.songs.list():
                print(song.name)
        """
        return Paginator(self._core, "/songs", _query([('song_category_ids[]', song_category_ids), ('ids[]', ids), ('practice', practice), ('key_of_arrangement', key_of_arrangement), ('name', name), ('query', query), ('include[]', include), ('limit', limit)]), models.Song)

