class WikiResource(Resource):
    """`client.wiki`"""

    def __init__(self, core: _t.Any) -> None:
        super().__init__(core)
        self.categories = WikiCategoriesResource(core)

    def list_pages(
        self,
        *,
        limit: _t.Optional[int] = None,
        query: _t.Optional[str] = None,
        wiki_category_ids: _t.Optional[_t.List[int]] = None,
        order_fields: _t.Optional[_t.List[_t.Literal['createdDate', 'modifiedDate', 'modifiedPerson', 'title', 'wikiCategoryId', 'wikiCategoryName']]] = None,
        order_directions: _t.Optional[_t.List[_t.Literal['ASC', 'DESC']]] = None,
        include: _t.Optional[_t.List[_t.Literal['preview', 'text']]] = None,
        preview_length: _t.Optional[int] = None,
    ) -> Paginator[models.SimpleWikiPage]:
        """
        List wiki pages

        `GET /wiki/pages`

        Lists the latest revisions of non-system, non-redirect pages in viewable categories. Guest category permissions are supported. Omitted/empty wiki_category_ids selects every viewable category; inaccessible IDs are silently dropped. Without query, ordering defaults to display title, then GUID. With query, default ranking prefers matching category main pages, then title matches, exact-content matches and finally matches containing all query words. Explicit order_fields overrides ranking. Pagination is applied after finding and enriching all matching pages. Text is omitted unless include[]=text; include[]=preview returns an unrendered stored-text prefix, which may contain raw HTML. searchPreview is independently included when query is supplied. meta contains page count and pagination total/limit/current/lastPage; lastPage is 0 for no results.

        Args:
            limit: Maximum page size.
            query: Trimmed search term. SQL LIKE wildcard characters % and _ are interpreted by the backend.
            wiki_category_ids: Wiki category IDs that should be included. If none are given, all categories the user can view are included. Categories the user is not allowed to view are silently filtered out.
            order_fields: Fields used to sort the result. Multiple fields are applied in the given order. If omitted while `query` is present, results are sorted by search relevance.
                Allowed values: `createdDate`, `modifiedDate`, `modifiedPerson`, `title`, `wikiCategoryId`, `wikiCategoryName`.
            order_directions: Sort directions matching `order_fields[]` by position. Missing directions default to `ASC`.
                Allowed values: `ASC`, `DESC`.
            include: text returns Markdown or sanitized HTML; preview returns a raw stored-text prefix without HTML sanitization.
                Allowed values: `preview`, `text`.
            preview_length: Maximum number of characters returned in `textPreview` when `include[]=preview` is requested. Ignored without `include[]=preview`.

        Example::

            for page in client.wiki.list_pages():
                print(page.title)
        """
        return Paginator(self._core, "/wiki/pages", _query([('limit', limit), ('query', query), ('wiki_category_ids[]', wiki_category_ids), ('order_fields[]', order_fields), ('order_directions[]', order_directions), ('include[]', include), ('preview_length', preview_length)]), models.SimpleWikiPage)

    def list_search(
        self,
        *,
        query: str,
        wiki_category_ids: _t.Optional[_t.List[int]] = None,
    ) -> _t.List[models.WikiSearchResult]:
        """
        Full-text search across wiki pages

        `GET /wiki/search`

        Searches latest non-system, non-redirect pages in categories the current user or guest can view. Omitted/empty wiki_category_ids means all viewable categories; inaccessible categories are silently dropped. Results are grouped by relevance: category-name main pages, title matches (shorter first), exact text matches and then matches containing all query words. Results are deduplicated by GUID and are not paginated. The query is not trimmed; SQL LIKE wildcard characters % and _ are interpreted. Results contain domain-object links and a text preview with Markdown emphasis for matches, not the full page. For paginated page resources, use GET /wiki/pages.

        Args:
            query: Search term. Must contain at least one character.
            wiki_category_ids: Wiki categories that should be searched. If none are given, all categories the user can view are searched. Categories the user is not allowed to view are silently filtered out.

        Example::

            for search in client.wiki.list_search(query="welcome"):
                print(search.title)
        """
        return _t.cast(_t.List[models.WikiSearchResult], self._call('GET', "/wiki/search", _query([('query', query), ('wiki_category_ids[]', wiki_category_ids)]), None, _t.List[models.WikiSearchResult], envelope=True))


